{"command": "cd /work/workspace/documents && (command -v pdftotext && pdftotext -layout employment_agreement_excerpt.pdf - ) || python3 -c "
import re,zlib
d=open('employment_agreement_excerpt.pdf','rb').read()
print(len(d),'bytes')
for m in re.finditer(rb'stream\r?\n(.*?)endstream', d, re.S):
    try:
        t=zlib.decompress(m.group(1))
        s=re.findall(rb'\((.*?)\)\s*Tj|\[(.*?)\]\s*TJ', t, re.S)
        out=[]
        for a,b in s:
            out.append(a.decode('latin-1') if a else b.decode('latin-1'))
        txt=''.join(out).replace('\\\\(','(').replace('\\\\)',')')
        if txt.strip(): print(txt)
    except Exception: pass
""}
